exports.id=1481,exports.ids=[1481],exports.modules={58330:(e,t,i)=>{Promise.resolve().then(i.bind(i,37912)),Promise.resolve().then(i.bind(i,96968)),Promise.resolve().then(i.t.bind(i,79404,23))},37912:(e,t,i)=>{"use strict";i.d(t,{FAQAccordion:()=>s});var a=i(10326),n=i(17577),r=i(6694);function s({faqs:e}){let[t,i]=(0,n.useState)(null);return a.jsx("div",{className:"space-y-4",children:e.map((e,n)=>(0,a.jsxs)("div",{className:"bg-white rounded-xl border border-slate-200 overflow-hidden transition-all duration-300 hover:border-slate-300",children:[(0,a.jsxs)("button",{onClick:()=>i(t===n?null:n),className:"w-full flex items-center justify-between p-5 text-left","data-testid":`faq-${n}`,children:[a.jsx("span",{className:"font-medium text-slate-900 pr-4",children:e.q}),a.jsx("div",{className:`transition-transform duration-300 flex-shrink-0 ${t===n?"rotate-180":""}`,children:a.jsx(r.Z,{className:"w-5 h-5 text-slate-400"})})]}),a.jsx("div",{className:`overflow-hidden transition-all duration-300 ${t===n?"max-h-48 opacity-100":"max-h-0 opacity-0"}`,children:a.jsx("div",{className:"px-5 pb-5 text-slate-600",children:e.a})})]},n))})}},6390:(e,t,i)=>{"use strict";i.d(t,{b:()=>a});let a=(0,i(68570).createProxy)(String.raw`/app/frontend/components/FAQAccordion.tsx#FAQAccordion`)},3577:(e,t,i)=>{"use strict";i.d(t,{$2:()=>r,C9:()=>d,Cc:()=>p,M:()=>n,O7:()=>a,RQ:()=>x,X5:()=>g,aF:()=>c,cW:()=>s,cX:()=>m,kc:()=>o,rz:()=>l,uv:()=>h});let a={"orthodontics-aligners":{minEUR:1500,maxEUR:6e3,minBGN:3e3,maxBGN:12e3,note:"Прозрачни алайнери (Invisalign, Spark, Angel Aligner и др.)"},"orthodontics-braces":{minEUR:1e3,maxEUR:4e3,minBGN:2e3,maxBGN:8e3,note:"Метални и керамични брекети"},"implant-single":{minEUR:800,maxEUR:2e3,minBGN:1600,maxBGN:4e3,note:"Един зъб (имплант + корона)"},"implant-all-on-4":{minEUR:6e3,maxEUR:2e4,minBGN:12e3,maxBGN:4e4,note:"All-on-4 / All-on-6 (една челюст)"},veneers:{minEUR:250,maxEUR:900,minBGN:500,maxBGN:1800,note:"На зъб (порцеланови фасети)"},bonding:{minEUR:80,maxEUR:250,minBGN:160,maxBGN:500,note:"На зъб (композитен бондинг)"},whitening:{minEUR:150,maxEUR:400,minBGN:300,maxBGN:800,note:"Професионално избелване"},"tmj-therapy":{minEUR:200,maxEUR:1500,minBGN:400,maxBGN:3e3,note:"Шини и TMJ терапия"},"sleep-apnea":{minEUR:500,maxEUR:2500,minBGN:1e3,maxBGN:5e3,note:"Орални апарати за сънна апнея"}},n="Цените са ориентировъчни и зависят от сложност, план и клиника.",r="При много сложни случаи при топ специалисти може да достигне горната граница.",s="Най-важният фактор е опитът на ортодонта и правилната диагноза. Марката сама по себе си не гарантира резултат.",l="Информацията е образователна и не замества преглед.";function o(e){switch(e){case"orthodontics":return[a["orthodontics-aligners"],a["orthodontics-braces"]];case"implants":return[a["implant-single"],a["implant-all-on-4"]];case"cosmetic-dentistry":return[a.veneers,a.bonding,a.whitening];case"tmj":return[a["tmj-therapy"]];case"sleep-airway":return[a["sleep-apnea"]];default:return[]}}let c=[{name:"Invisalign",slug:"invisalign",suitableCases:"Леки до сложни случаи (зависи от плана и лекаря)",comfort:"Висок комфорт, тънък материал (може да варира)",aesthetics:"Почти невидими",availability:"Широко разпространен в България",orthodontistControl:"Пълен контрол от ортодонта, дигитално планиране",priceRange:"€2 000 – €6 000",priceBGN:"≈ 4 000 – 12 000 лв."},{name:"Spark",slug:"spark",suitableCases:"Леки до средни случаи (зависи от плана и лекаря)",comfort:"Висок комфорт, по-ясен материал (може да варира)",aesthetics:"Почти невидими",availability:"Нарастваща наличност в България",orthodontistControl:"Пълен контрол от ортодонта, дигитално планиране",priceRange:"€1 800 – €5 000",priceBGN:"≈ 3 600 – 10 000 лв."},{name:"Angel Aligner",slug:"angel-aligner",suitableCases:"Леки до средни случаи (зависи от плана и лекаря)",comfort:"Добър комфорт (може да варира)",aesthetics:"Почти невидими",availability:"Налични в избрани клиники",orthodontistControl:"Пълен контрол от ортодонта, дигитално планиране",priceRange:"€1 500 – €4 000",priceBGN:"≈ 3 000 – 8 000 лв."}],m={title:"Как подбираме опции за клиники",description:'Работим само с клиники, които отговарят на нашите критерии за качество и прозрачност. Не класираме и не препоръчваме конкретна клиника като "най-добра" — изборът зависи от вашия случай и предпочитания.',criteria:["Проверена квалификация на специалистите","Прозрачно ценообразуване","Положителна обратна връзка от пациенти"]},d={title:"Какво ще получите",items:["Препоръка за подходящ тип лечение според вашия случай","Ориентировъчни цени преди да говорите с клиника","2–3 опции за клиники, които отговарят на критериите ни","Възможност за безплатна консултация"]},p={orthodontics:["Криви или накривени зъби","Препокриване на зъбите","Разстояния между зъбите","Неправилна захапка (overbite, underbite, crossbite)","Трудности при дъвчене или говорене","Челюстни болки или главоболие от захапката","Желание за по-красива усмивка","Препоръка от общопрактикуващ зъболекар"],implants:["Липсващ един или повече зъби","Нестабилна зъбна протеза","Трудности при дъвчене на храна","Костна загуба в челюстта","Желание за трайно решение","Здрави съседни зъби (за избягване на мост)","Дискомфорт от подвижна протеза","Препоръка от зъболекар"],"cosmetic-dentistry":["Потъмнели или оцветени зъби","Счупени или напукани зъби","Неравномерни или неправилни форми","Разстояния между зъбите","Стари пломби, които се виждат","Желание за по-бяла усмивка","Подготовка за важно събитие","Ниско самочувствие заради усмивката"],"sleep-airway":["Силно хъркане","Прекъсване на дишането по време на сън","Събуждане с усещане за задушаване","Прекомерна дневна сънливост","Главоболие сутрин","Затруднена концентрация","Диагностицирана сънна апнея","Непоносимост към CPAP апарат"],tmj:["Болка в челюстната става","Щракане или скърцане при отваряне на устата","Затруднено отваряне на устата","Болка при дъвчене","Честа главоболие или мигрена","Болка в ушите без инфекция","Скърцане със зъби (бруксизъм)","Напрежение в лицевите мускули"]},h={orthodontics:{intro:"Ортодонтията е специализиран клон на денталната медицина, който се занимава с диагностика, превенция и корекция на неправилно позиционирани зъби и челюсти.",paragraphs:["Съвременната ортодонтия предлага разнообразие от методи за изправяне на зъбите — от традиционните метални брекети до почти невидимите прозрачни алайнери като Invisalign, Spark и Angel Aligner. Изборът на метод зависи от конкретния проблем, възрастта на пациента и личните предпочитания.","Ортодонтското лечение не е само козметично — правилната захапка подобрява функцията на дъвчене, улеснява хигиената и предотвратява бъдещи проблеми като износване на емайла, заболявания на венците и челюстни дисфункции.","Лечението обикновено продължава между 12 и 24 месеца, но леките случаи могат да се коригират и за 6 месеца. След приключване на активното лечение се носи ретейнер за запазване на резултата."]},implants:{intro:"Зъбните импланти са съвременното решение за заместване на липсващи зъби, което най-близко имитира естествените зъби по функция и външен вид.",paragraphs:["Имплантът представлява титанов винт, който се поставя в челюстната кост и служи като изкуствен корен. Върху него се монтира корона, мост или протеза. Титанът се интегрира с костта (остеоинтеграция), осигурявайки стабилна основа.","За разлика от мостовете, имплантите не изискват пилене на съседните здрави зъби. Те предотвратяват костната загуба, която настъпва след загуба на зъб, и възстановяват пълноценно функцията на дъвчене.","Процедурата се извършва под локална анестезия и е безболезнена. Периодът на възстановяване е 3-6 месеца, през които костта зараства около импланта. При подходящи условия е възможно незабавно натоварване с временни зъби."]},"cosmetic-dentistry":{intro:"Естетичната стоматология обхваща процедури, насочени към подобряване на външния вид на усмивката — цвят, форма, подредба и цялостна хармония на зъбите.",paragraphs:["Професионалното избелване е една от най-популярните процедури, която може да изсветли зъбите с 3-8 нюанса за едно посещение. Използват се безопасни формули, които не увреждат емайла.","Порцелановите фасети са тънки керамични пластини, които се залепват върху предната повърхност на зъбите. Те коригират цвят, форма и малки несъвършенства, създавайки идеална усмивка за 10-15 години.","Композитният бондинг е по-достъпна алтернатива за корекция на малки дефекти — счупвания, разстояния или неравности. Процедурата се извършва за едно посещение без изпиляване на зъба."]},"sleep-airway":{intro:"Денталната медицина предлага ефективни решения за проблеми със съня като хъркане и обструктивна сънна апнея чрез специализирани орални апарати.",paragraphs:["Оралните апарати (мандибуларни advancement устройства) позиционират долната челюст леко напред по време на сън, което отваря дихателните пътища и намалява или премахва хъркането и апнеята.","Тези апарати са одобрена алтернатива на CPAP машините при лека до умерена сънна апнея. Те са удобни за пътуване, не издават шум и не изискват електричество.","Индивидуално изработеният апарат се прави по отпечатък на вашите зъби, което гарантира комфорт и ефективност. Повечето пациенти свикват за 1-2 седмици."]},tmj:{intro:"TMJ (темпоромандибуларната става) е ставата, която свързва долната челюст с черепа. Дисфункциите в тази област причиняват болка и ограничена подвижност.",paragraphs:["Симптомите на TMJ дисфункция включват болка в челюстта, щракане или скърцане при отваряне на устата, главоболие, болки в ушите и затруднено дъвчене. Причините са разнообразни — стрес, бруксизъм, травма или неправилна захапка.","Лечението обикновено започва с консервативни методи — шини за нощно носене, физиотерапевтични упражнения и промени в навиците. В повечето случаи това е достатъчно за облекчаване на симптомите.","Стабилизиращата шина (сплинт) е основен инструмент в терапията. Тя се носи предимно през нощта и предпазва зъбите от скърцане, като същевременно релаксира челюстните мускули."]}},x={aligners:{title:"Алайнери (прозрачни)",pros:["Почти невидими","Свалят се при хранене и хигиена","По-малко дискомфорт (може да варира)","По-лесна орална хигиена","По-малко посещения при лекаря (може да варира)"],cons:["Изискват дисциплина (22+ часа носене)","Не са подходящи за всички случаи","Могат да се изгубят или счупят","Обикновено по-висока цена"]},braces:{title:"Брекети",pros:["Подходящи за всички случаи","Не изискват самодисциплина","Постоянно действие 24/7","Обикновено по-ниска цена","По-предвидими резултати при сложни случаи"],cons:["Видими (освен лингвалните)","Ограничения в храната","По-трудна хигиена","Може да причинят дискомфорт","По-чести посещения при лекаря"]}},g=[{q:"Коя марка алайнери е най-добра?",a:'Няма универсално "най-добра" марка. Резултатът зависи преди всичко от опита на ортодонта и правилната диагноза. Invisalign, Spark и Angel Aligner са качествени системи с доказана ефективност.'},{q:"Каква е разликата в цената между марките?",a:"Invisalign обикновено е в диапазона €2 000 – €6 000, Spark €1 800 – €5 000, Angel Aligner €1 500 – €4 000. Цените зависят от сложността на случая и клиниката."},{q:"Мога ли да избера марката сам?",a:"Можете да изразите предпочитание, но ортодонтът ще препоръча системата, която е най-подходяща за вашия конкретен случай."},{q:"Колко време трае лечението с алайнери?",a:"Обикновено между 6 и 24 месеца, в зависимост от сложността. Леките случаи могат да се завършат за 6-12 месеца."},{q:"Болезнено ли е носенето на алайнери?",a:"Може да има лек дискомфорт при смяна на нов алайнер, но обикновено отминава за 1-2 дни. Повечето пациенти свикват бързо."},{q:"Какво се случва след лечението?",a:"След приключване на активното лечение се носи ретейнер (фиксиран или подвижен), за да се запази резултатът."},{q:"Подходящи ли са алайнерите за деца?",a:"Да, има специални системи за тийнейджъри. За по-малки деца обикновено се препоръчват други методи, определени от ортодонта."},{q:"Покрива ли здравната каса алайнерите?",a:"Обикновено не. Ортодонтското лечение рядко се покрива от НЗОК. Много клиники предлагат разсрочено плащане."}]},71640:(e,t,i)=>{"use strict";i.d(t,{Z:()=>a});let a=(0,i(5487).Z)("AlertCircle",[["circle",{cx:"12",cy:"12",r:"10",key:"1mglay"}],["line",{x1:"12",x2:"12",y1:"8",y2:"12",key:"1pkeuh"}],["line",{x1:"12",x2:"12.01",y1:"16",y2:"16",key:"4dfq90"}]])},23336:(e,t,i)=>{"use strict";i.d(t,{Z:()=>a});let a=(0,i(5487).Z)("ArrowLeft",[["path",{d:"m12 19-7-7 7-7",key:"1l729n"}],["path",{d:"M19 12H5",key:"x3x0zl"}]])},23231:(e,t,i)=>{"use strict";i.d(t,{Z:()=>a});let a=(0,i(5487).Z)("ArrowRight",[["path",{d:"M5 12h14",key:"1ays0h"}],["path",{d:"m12 5 7 7-7 7",key:"xquz4c"}]])},57586:(e,t,i)=>{"use strict";i.d(t,{Z:()=>a});let a=(0,i(5487).Z)("CheckCircle",[["path",{d:"M22 11.08V12a10 10 0 1 1-5.93-9.14",key:"g774vq"}],["polyline",{points:"22 4 12 14.01 9 11.01",key:"6xbx8j"}]])}};